parameters.jsCode:
const groqResponse = $input.first().json;
const contentString = groqResponse.choices[0].message.content;
const parsed = JSON.parse(contentString);

const originalInquiry = $('Webhook').first().json.body.inquiry;

return {
  json: {
    inquiry: originalInquiry,
    category: parsed.category,
    priority: parsed.priority,
    summary: parsed.summary,
    extracted_name: parsed.extracted.name,
    extracted_email: parsed.extracted.email,
    extracted_phone: parsed.extracted.phone,
    extracted_property: parsed.extracted.property_interest,
    extracted_timeline: parsed.extracted.timeline
  }
};

const embedding = $('Embed Inquiry').item.json.embedding.values;
const vectorString = '[' + embedding.join(',') + ']';

return {
  json: {
    vector_string: vectorString
  }
};

parameters.query:
select id, source, title, content, similarity
from match_faq_chunks(
  '{{ $json.vector_string }}'::vector,
  0.3,
  3
);

parameters.jsCode:
const inquiry = $('Code in JavaScript').item.json.inquiry;
const chunks = $('Retrieve FAQ Chunks').all();

const context = chunks
  .map(i => `--- ${i.json.source} ---\n${i.json.content}`)
  .join('\n\n');

const body = {
  model: 'openai/gpt-oss-20b',
  messages: [
    {
      role: 'system',
      content: 'You are a customer service assistant for a fictional property developer. Draft a reply to the customer\'s inquiry, grounded ONLY in the provided knowledge base excerpts. If the knowledge base doesn\'t cover the inquiry, say so politely and suggest contacting the sales team. Do not invent facts. Keep the reply to 3-5 sentences, professional and warm.'
    },
    {
      role: 'user',
      content: `Customer inquiry:\n${inquiry}\n\nKnowledge base excerpts:\n${context}`
    }
  ],
  temperature: 0.3
};

return {
  json: {
    body_string: JSON.stringify(body)
  }
};
